package job

import "errors"

type State int

const (
    StateUnknown State = iota
    StateQueued
    StateRunning
    StateDone
)

type Job struct {
    State     State
    StateName string
    Done      bool
}

func New(name string) (Job, error) {
    switch name {
    case "queued":
        return Job{State: StateQueued, StateName: name}, nil
    case "running":
        return Job{State: StateRunning, StateName: name}, nil
    case "done":
        return Job{State: StateDone, StateName: name, Done: true}, nil
    default:
        return Job{}, errors.New("unknown state")
    }
}

func (j Job) IsDone() bool {
    return j.Done || j.State == StateDone || j.StateName == "done"
}
